#!/usr/bin/env python3# -*- coding: utf-8 -*-"""خزنة — Telegram media saver bot (public).Sends back videos and photos from a link you send. Uses yt-dlp for video/audioand gallery-dl for image galleries. No cookies, no private accounts, no massscraping. Each request is limited and files above Telegram's bot limit arerejected with a clear message.Run: BOT_TOKEN=... python khazna_bot.py"""import asyncioimport osimport reimport subprocessimport tempfileimport threadingimport timefrom collections import defaultdict, dequefrom http.server import BaseHTTPRequestHandler, ThreadingHTTPServerfrom pathlib import Pathimport requestsimport yt_dlpfrom telegram import Updatefrom telegram.constants import ChatAction, ParseModefrom telegram.ext import Application, CommandHandler, ContextTypes, MessageHandler, filters# ---- limits ----MAX_UPLOAD_BYTES = 45 * 1024 * 1024   # Telegram bot API hard limit is 50 MBMAX_IMAGES = 10RATE_WINDOW = 60RATE_MAX = 5URL_RE = re.compile(r"https?://[^\s<>\"']+", re.I)VIDEO_EXT = {".mp4", ".webm", ".mkv", ".mov", ".m4v"}IMAGE_EXT = {".jpg", ".jpeg", ".png", ".webp", ".gif"}_rates = defaultdict(deque)_log_lock = threading.Lock()LAST_EVENT = {"text": "", "stage": "", "error": ""}# YouTube refuses known datacenter IPs (Render, VPS, CI). A residential proxy# supplied through PROXY_URL is the only reliable fix for a public bot.YOUTUBE_BLOCK_MARKERS = (    "sign in to confirm you're not a bot",    "sign in to confirm you are not a bot",    "failed to extract any player response",    "captcha",)def friendly_error(text):    """Turn a raw yt-dlp error into a message a user can act on."""    t = str(text).lower()    if any(marker in t for marker in YOUTUBE_BLOCK_MARKERS):        return (            "يوتيوب يمنع التحميل من سيرفرات الاستضافة 🤍 "            "البوت يحتاج بروكسي سكني (PROXY_URL) عشان يشتغل للناس كلها."        )    return f"ما قدرت أحمّله 🤍 ({str(text)[:120]})"async def health_server():    """Tiny HTTP endpoint so free hosts see an inbound port and stay 'up'."""    port = int(os.environ.get("PORT", "7860"))    class H(BaseHTTPRequestHandler):        def do_GET(self):            import json as _j            if self.path.startswith("/debug"):                body = _j.dumps(LAST_EVENT, ensure_ascii=False).encode("utf-8")                self.send_response(200)                self.send_header("Content-Type", "application/json; charset=utf-8")            else:                body = "خزنة ok v10 (proxy-ready)".encode("utf-8")                self.send_response(200)                self.send_header("Content-Type", "text/plain; charset=utf-8")            self.send_header("Content-Length", str(len(body)))            self.end_headers()            self.wfile.write(body)        def log_message(self, *a):            pass    server = ThreadingHTTPServer(("0.0.0.0", port), H)    threading.Thread(target=server.serve_forever, daemon=True).start()    print(f"health endpoint on :{port}", flush=True)def allowed(chat_id):    now = time.time()    q = _rates[chat_id]    while q and q[0] < now - RATE_WINDOW:        q.popleft()    if len(q) >= RATE_MAX:        return False    q.append(now)    return Truedef clean_url(u):    return u.rstrip(".,;:!؟?)]}>\u200b")def host_of(u):    m = re.match(r"https?://([^/]+)", u, re.I)    return (m.group(1).lower() if m else "").replace("www.", "")def size_text(n):    return f"{n / 1024 / 1024:.1f} MB"async def start(update: Update, context: ContextTypes.DEFAULT_TYPE):    await update.message.reply_text(        "هلا 🤍 أنا خزنة. أرسل لي رابط فيديو أو صور من يوتيوب، إنستغرام، تيك توك "        "أو أي موقع مدعوم، وأرسلها لك هنا.\n\n"        "أوامر: /video رابط • /photo رابط • /help\n"        "الحد: 45 MB للملف، 10 صور، 5 طلبات بالدقيقة."    )async def help_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):    await update.message.reply_text(        "فقط أرسل الرابط وأنا أختار 🤍\n"        "/video رابط — فيديو\n"        "/photo رابط — صور من ألبوم أو منشور\n"        "ما أفتح حسابات خاصة ولا أطلب كوكيز."    )async def download_video(update, url):    out = Path(tempfile.mkdtemp(prefix="khazna-"))    try:        opts = {            "outtmpl": str(out / "%(id)s.%(ext)s"),            "format": "best[filesize<=45M]/best[filesize_approx<=45M]/best[ext=mp4][height<=480]/best[height<=480]/worst[ext=mp4]/worst",            "quiet": True,            "noplaylist": True,            "no_warnings": True,            "socket_timeout": 25,            "retries": 2,            "extractor_args": {"youtube": {"player_client": ["android", "tv", "web_safari"]}},        }        proxy = os.environ.get("PROXY_URL", "").strip()        if proxy:            opts["proxy"] = proxy        loop = asyncio.get_running_loop()        info = await loop.run_in_executor(None, lambda: _ytdlp_download(opts, url))        files = [p for p in out.iter
